const nextFreeStart = `-- name: NextFreeStart :one
WITH busy AS (
  SELECT b.period FROM bookings b
  WHERE b.equipment_id = $3 AND booking_holds_slot(b.status) AND upper(b.period) > $1::timestamptz
  UNION ALL
  SELECT a.period FROM availability_blocks a WHERE a.equipment_id = $3 AND upper(a.period) > $1::timestamptz
), candidates AS (
  SELECT $1::timestamptz AS s
  UNION SELECT upper(period) FROM busy
)
SELECT c.s::timestamptz AS start_at FROM candidates c
WHERE c.s >= $1::timestamptz
  AND NOT EXISTS (SELECT 1 FROM busy WHERE busy.period && tstzrange(c.s, c.s + make_interval(secs => $2::float8 * 3600), '[)'))
ORDER BY c.s LIMIT 1
`

